'use strict';
const HAND_MAPS={
shanghai:{line:'一江两岸，连接老城与新城',terrain:'黄浦江是读懂上海的主线：浦西的历史街区与浦东的现代天际线隔江相望，虹桥与浦东机场分布于城市不同方向。',alt:'上海手绘地图：黄浦江、外滩、陆家嘴、人民广场与东西两侧交通门户。',spots:[['外滩',52,43,'culture','黄浦江西岸的历史建筑群，与对岸陆家嘴共同构成上海鲜明的城市景观。','东岸与西岸隔江相望，过江路线仍要按实际出行安排。'],['陆家嘴',70,32,'culture','浦东的金融商务区与高层建筑群；东方明珠是这里具有辨识度的地标。','天际线、滨江公共空间与商务楼宇是不同的体验场所。'],['人民广场',39,39,'culture','中心城区公共文化与交通节点，周边集聚博物馆、剧院和商业。','文化设施与轨道入口需按具体目的地核对。'],['徐家汇',27,62,'education','浦西西南部的重要商业、历史与教育片区，周边连接多种城市功能。','它与上海交通大学其他校区的空间位置不能混同。'],['虹桥枢纽',11,34,'transport','位于城市西侧，虹桥站、机场和轨道交通共同组成综合交通枢纽。','机场T1、T2与铁路进站口是不同目的地。'],['浦东机场',83,76,'transport','位于城市东侧的航空门户，与虹桥枢纽相距较远。','航站楼、首末班接驳与夜间抵达方式需另行确认。']]},
beijing:{line:'沿着中轴，读懂层层展开的首都',terrain:'北京的古城空间围绕中轴展开，西北部集聚湖山与高校资源，首都机场位于城市东北方向。',alt:'北京手绘地图：故宫、中轴、天坛、西北湖山与高校、东北首都机场。',spots:[['故宫',51,47,'culture','古城中轴上的宫殿建筑群，也是认识北京都城历史的重要起点。','参观入口、预约与展览安排应看当前官方说明。'],['天安门周边',51,58,'culture','故宫以南的城市公共空间，周边连接国家级文化与历史资源。','不同场所的预约和访问安排各自独立。'],['天坛',65,74,'culture','位于古城东南部的历史礼制空间，建筑与园林共同形成城市文化景观。','公园与具体建筑的参观范围需分别核对。'],['中关村与高校片区',26,26,'education','北京西北部的重要科教区域，联系北京大学、清华大学和科研机构。','同一片区内不同学校、院系与园区仍有独立边界。'],['颐和园',14,19,'nature','西北方向的湖山与历史园林，以昆明湖和万寿山构成鲜明的景观结构。','城市尺度被图中压缩，实际距离与步行强度需另外评估。'],['首都机场',85,15,'transport','位于北京东北方向的航空门户；大兴机场另在南部，未画入此图。','两座机场不可互换，出发前以机票和航站楼信息为准。']]},
shenzhen:{line:'沿海岸展开，产业片区连接山与海',terrain:'深圳沿东西方向展开，深圳湾与南山连接西部城市生活，福田和罗湖构成不同中心，大鹏半岛提供另一种海岸尺度。',alt:'深圳手绘地图：东西向城市、深圳湾、南山、福田、罗湖与大鹏海岸。',spots:[['福田中心区',46,42,'culture','市民中心周边集聚公共文化、商务和城市公共空间，是理解深圳中心区的一处入口。','文化场馆、办公区和公园的实际出入口并不相同。'],['深圳湾',33,56,'nature','城市西南方向的滨海公共空间，联系海岸步行与日常休闲。','炎热、暴雨和具体入口会影响户外体验。'],['南山',23,40,'education','西部的重要科技、商务与居住片区，高校与产业网络彼此联系。','片区很大，应以具体学校或园区规划路线。'],['深圳大学周边',19,48,'education','粤海校区位于南山，大学与周边城市产业空间形成近距离联系。','粤海校区与其他校区需按目的地分别核对。'],['罗湖铁路节点',69,46,'transport','深圳站与罗湖口岸附近的交通空间联系铁路、轨道与跨境出行。','深圳站、深圳北站与福田站是不同车站。'],['大鹏半岛',91,70,'nature','位于深圳东部的海岸与山地，保留与密集中心区不同的自然和文化景观。','中心区到海岸的距离在示意图中被压缩，需安排实际交通。']]},
chongqing:{line:'两江汇合，山城在高差中展开',terrain:'嘉陵江与长江在朝天门交汇，渝中半岛、北部铁路片区与南山隔水相望；高差与跨江通道共同决定城市体验。',alt:'重庆手绘地图：长江与嘉陵江交汇、渝中半岛、洪崖洞、朝天门、磁器口与南山。',spots:[['洪崖洞',55,60,'culture','靠近嘉陵江的山地建筑景观，展示重庆层叠的城市空间。','观景平台、道路与江岸可能处于不同高度。'],['朝天门',72,46,'nature','嘉陵江与长江的汇合处，提供认识两江与渝中半岛的直观视角。','河岸与道路入口的高差影响步行路径。'],['解放碑',47,50,'culture','渝中半岛的重要商业与城市记忆节点，周边街区密度较高。','短距离步行也可能需要台阶、坡道或垂直交通。'],['磁器口',16,19,'culture','位于嘉陵江沿岸的历史街区，在中心区以西北方向呈现另一种街巷生活。','它与渝中半岛相距较远，图中位置仅作构图示意。'],['重庆北站',40,12,'transport','位于北部龙头寺片区的铁路枢纽，联系多种城市交通。','重庆北站与重庆西站分属不同片区。'],['南山',84,77,'nature','长江南侧的山地提供登高与城市眺望，也形成与半岛不同的生活空间。','进山路线、坡度与夜间返程要分别核对。']]},
suzhou:{line:'在水网之间，寻找古城与新城',terrain:'古城的运河与街巷构成密集水网，金鸡湖位于东侧，太湖在城市西部；园林与产业新城提供两种不同尺度。',alt:'苏州手绘地图：古城水网、苏州博物馆、拙政园、平江路、虎丘与金鸡湖。',spots:[['苏州博物馆',40,29,'culture','本馆位于古城北部，建筑与园林环境相互呼应；另有西馆。','本馆和西馆位置不同，预约与路线需按馆区核对。'],['拙政园',54,29,'culture','古城东北部的代表性园林，以水、建筑和植物组织空间。','具体入口、预约与开放安排需看当期说明。'],['平江路',50,49,'culture','古城东侧的历史街区，街巷与河道紧密交织。','步行游览与沿街居民生活共处，入口与通行空间需留意。'],['虎丘',23,20,'culture','古城西北方向的重要历史景观，高低起伏与塔景形成辨识度。','图中压缩距离，实际到达方式需另外规划。'],['金鸡湖',82,48,'nature','古城以东的开放湖泊与滨水城市空间，联系苏州工业园区生活。','湖岸不同片区的入口、活动与交通体验各异。'],['苏州站',41,12,'transport','古城北侧的铁路客运节点，与苏州北站分属不同位置。','出行按票面站名核对，不要把两个车站混为一处。']]},
chengdu:{line:'从老城到新区，河道穿过平原街区',terrain:'成都中心城位于平原，锦江水系与街区相互交织；文化空间偏重老城，铁路与高校资源沿不同方向延伸。',alt:'成都手绘地图：锦江、天府广场、武侯祠、杜甫草堂、华西片区与东北熊猫基地。',spots:[['天府广场',51,43,'culture','中心城区的重要公共空间，成都博物馆位于其西侧。','文化参观、轨道入口与广场活动需分别安排。'],['武侯祠',33,63,'culture','位于中心城西南部的历史文化资源，与周边街区共同构成成都文化体验。','具体展览与开放规则需要查阅当期官方说明。'],['杜甫草堂',17,49,'culture','中心城西部的文学历史与园林空间，适合从诗歌传统切入成都。','它与其他中心景点并非紧邻，实际路程要另行规划。'],['华西片区',52,79,'medical','四川大学医学与附属医院资源在中心城南部形成具有辨识度的片区。','华西医院、华西第二医院和具体院区不可混同。'],['成都东站',82,55,'transport','位于中心城东侧的重要铁路门户，与其他成都铁路车站分开。','车次、进站口与地面接驳要按具体行程核对。'],['熊猫基地',80,13,'nature','位于中心城东北方向的成都大熊猫繁育研究基地，是具有地方辨识度的生态与研究资源。','它不是家门口公园，预约和园内步行范围需要提前了解。']]},
hangzhou:{line:'湖、江与运河，塑造三种城市尺度',terrain:'西湖与群山位于老城西侧，钱塘江在东南侧展开，大运河联系城市北部；湖岸生活与现代滨江空间各有节奏。',alt:'杭州手绘地图：西湖、灵隐群山、湖岸古塔、浙江大学、大运河与钱塘江。',spots:[['灵隐与群山',11,39,'nature','西湖以西的山地与寺院环境，呈现杭州湖山相邻的空间特点。','山路、公园与寺院的入口和开放规则应分别核对。'],['西湖南岸',39,57,'nature','南岸的山水与历史景观连接湖面、步行空间和塔景。','图中压缩湖岸尺度，不同入口的步行范围各异。'],['浙江大学片区',30,13,'education','浙江大学在杭州有不同校区，西湖西北方向联系玉泉等科教空间。','不同院系可能在紫金港、玉泉或其他校区，应核对具体地址。'],['大运河',55,12,'culture','城市北部的历史水道与沿线博物馆、工业遗产共同构成文化轴线。','运河沿线不是单一场馆，需按主题选择具体目的地。'],['湖东老城',60,46,'culture','西湖东侧的老城街区联系商业、历史与日常生活，体现湖与城的相邻关系。','热门湖岸与居住街区的生活体验并不完全相同。'],['杭州东站',82,22,'transport','位于中心城东北方向的铁路枢纽，联系长三角跨城出行。','杭州站、杭州东站和杭州西站是不同目的地。']]},
wuhan:{line:'两江三镇，湖泊延展城市生活',terrain:'汉江汇入长江，三镇在两江之间展开；东湖与高校资源位于城市东部，使江岸与湖岸形成不同的生活路径。',alt:'武汉手绘地图：长江与汉江、汉口、黄鹤楼、武汉大学、东湖与湖北省博物馆。',spots:[['汉口历史街区',35,30,'culture','长江与汉江交汇处以北的历史商业街区，保留不同年代的建筑与城市记忆。','街区范围较大，可按主题组织步行路线。'],['黄鹤楼',51,59,'culture','位于长江东侧的武昌，历史景观与江桥、城市视野共同形成辨识度。','登高、展览和周边步行涉及不同访问范围。'],['武汉大学',78,66,'education','主校区与东湖南岸、珞珈山环境相邻，大学与湖山形成独特联系。','校园活动与参访安排要通过正式入口核对。'],['东湖',85,35,'nature','城市东部的大型湖泊与绿道系统，各片区提供不同户外活动。','湖面与岸线在图中被压缩，实际路线长度与入口需另外规划。'],['湖北省博物馆',71,34,'culture','位于东湖西侧的省级文化资源，可与附近湖岸活动组合探索。','场馆预约与湖区出行应分别安排。'],['汉口站',23,13,'transport','汉口方向的重要铁路节点，与武昌站、武汉站分属不同位置。','三座主要车站不可互换，以车票目的地为准。']]},
nanjing:{line:'湖山环绕，历史层次落在城市空间',terrain:'长江位于城市西北与西侧，玄武湖和紫金山联系古城北部与东部；历史街区、高校和铁路门户沿不同方向展开。',alt:'南京手绘地图：长江、玄武湖、紫金山、南京博物院、总统府和南京大学。',spots:[['玄武湖',57,24,'nature','古城北部的湖泊公园，与城墙景观相邻，是日常休闲的重要入口。','湖岸、洲岛与城墙的访问范围分别核对。'],['紫金山',85,31,'nature','城市东部的山林与历史景观，形成登高与文化参观相邻的区域。','山路强度与景区、历史设施的访问规则不完全相同。'],['南京博物院',72,49,'culture','位于古城东侧的文化资源，以历史、艺术和专题馆藏展开多重叙事。','具体馆区、展览与预约需按官方说明确认。'],['总统府',52,47,'culture','长江路附近的近代历史建筑与展览空间，联系城市历史街区。','室内参观与周边步行属于不同访问安排。'],['南京大学鼓楼校区',38,32,'education','位于中心城的高校空间，与城市街区和历史环境联系紧密。','南京大学另有其他校区，院系地址需单独核对。'],['南京南站',55,84,'transport','位于中心城南侧的重要高铁枢纽，与南京站分属不同位置。','出行按车次及站名确认，不用一个枢纽代表所有铁路行程。']]}
};
HAND_MAPS.guangzhou={line:'珠江穿城，老城与新中轴相互呼应',terrain:'珠江把城市公共空间与两岸片区联系起来，西部老城、东部珠江新城与南部铁路门户构成不同方向，白云山位于中心城以北。',alt:'广州手绘地图：珠江、广州塔、珠江新城、沙面、陈家祠与白云山。',spots:[['广州塔',71,55,'culture','位于珠江南岸的城市地标，与北岸珠江新城形成相互呼应的天际线。','登塔、河岸步行与周边演出场所是不同体验。'],['珠江新城',68,33,'culture','珠江北岸的商务与文化片区，联系广东省博物馆、广州大剧院等资源。','场馆入口与办公街区的访问安排分别核对。'],['沙面',28,55,'culture','珠江沿岸的历史建筑与街区空间，呈现广州近代商贸的一个切面。','公共街巷与具体建筑内部的访问范围可能不同。'],['陈家祠',26,36,'culture','西部老城的重要建筑与工艺文化资源，适合了解岭南建筑细节。','具体展览与开放规则需要看官方信息。'],['白云山',70,11,'nature','中心城北部的山地与公共休闲资源，提供与密集城区不同的空间。','不同入口、坡度和上下山交通会改变体验。'],['广州南站',33,83,'transport','位于番禺方向的高铁枢纽，与老城铁路车站相距较远。','图中压缩距离，应按车票站名与具体接驳安排出行。']]};
function mapSpotMarkup(c){const m=HAND_MAPS[c.id];return m.spots.map((p,i)=>`<button class="sketch-pin ${state.mapSpot===i?'selected':''}" data-map-spot="${i}" style="left:${p[1]}%;top:${p[2]}%" aria-label="${c.name}手绘地标${i+1}：${esc(p[0])}" aria-pressed="${state.mapSpot===i}"><span>${i+1}</span></button>`).join('');}
function mapNote(c){const m=HAND_MAPS[c.id],p=m.spots[state.mapSpot]||m.spots[0];return `<div class="kicker">${FACET_TYPES[p[3]].short} / 地标与片区</div><h3>${esc(p[0])}</h3><p>${esc(p[4])}</p><p class="caption">${esc(p[5])}</p><button class="map-related" data-facet="${p[3]}" data-map-related="true">查看${FACET_TYPES[p[3]].label}切面</button>`;}
window.renderHandMap=function(c){const m=HAND_MAPS[c.id];return `<section class="panel city-sketch" id="city-sketch"><div class="sketch-heading"><div><div class="kicker">${c.en} / 手绘城市地图</div><h2>${esc(m.line)}</h2></div><button class="secondary" data-map-expand>放大地图</button></div><div class="sketch-layout"><div><div class="sketch-canvas"><img src="maps/${c.id}.webp" width="1536" height="1024" alt="${esc(m.alt)}" decoding="async" fetchpriority="high">${mapSpotMarkup(c)}<span class="sketch-north" aria-label="北向上">N<br>北</span></div><div class="sketch-place-list" aria-label="地图地标列表">${m.spots.map((p,i)=>`<button data-map-spot="${i}" class="${state.mapSpot===i?'selected':''}" aria-pressed="${state.mapSpot===i}"><span>${i+1}</span>${esc(p[0])}</button>`).join('')}</div></div><aside class="sketch-note"><p class="sketch-geography">${esc(m.terrain)}</p><div data-map-note aria-live="polite">${mapNote(c)}</div></aside></div><p class="sketch-caption">AI 生成的手绘示意图 · 北向上 · 地标位置与距离经构图简化，不按比例，不用于导航。</p><dialog class="map-dialog" id="map-dialog" aria-labelledby="map-dialog-title"><div class="map-dialog-head"><h2 id="map-dialog-title">${c.name} / 手绘城市地图</h2><button class="secondary" data-map-close>关闭</button></div><div class="sketch-canvas sketch-large"><img src="maps/${c.id}.webp" width="1536" height="1024" alt="${esc(m.alt)}" decoding="async">${mapSpotMarkup(c)}</div><div class="map-dialog-info" data-map-note aria-live="polite">${mapNote(c)}</div><p class="caption">手绘示意图，位置和比例经过简化。小屏幕可横向滚动查看大图。</p></dialog></section>`;};
document.addEventListener('click',e=>{const pin=e.target.closest('[data-map-spot]');if(pin){const i=Number(pin.dataset.mapSpot);if(!Number.isInteger(i)||!HAND_MAPS[state.city]?.spots[i])return;state.mapSpot=i;document.querySelectorAll('[data-map-spot]').forEach(n=>{n.classList.toggle('selected',Number(n.dataset.mapSpot)===i);n.setAttribute('aria-pressed',Number(n.dataset.mapSpot)===i);});document.querySelectorAll('[data-map-note]').forEach(n=>n.innerHTML=mapNote(selected()));return;}if(e.target.closest('[data-map-related]')){requestAnimationFrame(()=>document.querySelector('.facet-layout')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));return;}if(e.target.closest('[data-map-expand]')){$('#map-dialog')?.showModal();return;}if(e.target.closest('[data-map-close]')){$('#map-dialog')?.close();return;}if(e.target.closest('[data-open-map]')){setView('facets');requestAnimationFrame(()=>$('#city-sketch')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));return;}if(e.target.id==='map-dialog'){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
